static void ieee802154_if_setup ( struct net_device * dev ) { dev -> addr_len = IEEE802154_EXTENDED_ADDR_LEN ; memset ( dev -> broadcast , 0xff , IEEE802154_EXTENDED_ADDR_LEN ) ; dev -> needed_tailroom = IEEE802154_MAX_AUTH_TAG_LEN + IEEE802154_FCS_LEN ; dev -> mtu = IEEE802154_MTU - IEEE802154_FCS_LEN - dev -> hard_header_len ; dev -> tx_queue_len = 300 ; dev -> flags = IFF_NOARP | IFF_BROADCAST ; } 